    /**
     * Method to retrieve the Model via an FindModelQuery
     * @return 	query	FindModelQuery
     */
    @SuppressWarnings("unused")
    public Model find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Model - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
